 * Of `userIds`, the ones that are current members of `orgId`: live and active.
 * Removed and not-yet-active members are left out.
 */
export async function listCurrentMemberUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();
  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

/** The seat count every plan check compares against. */

