/**
 * Reference checks shared by the write services. Everything a change points at
 * (a parent issue, labels, an assignee, a project lead, a reply target) must be
 * usable from the workspace the change is made in.
 *
 * Each check runs before the change is written or announced, so a refusal
 * leaves nothing behind. A reference owned by another workspace is refused the
 * way every cross-workspace access is (`TenantScopeError`); one that is missing,
 * archived, not a current member or otherwise unusable is refused as not found.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { CommentId, IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Refuses a reference that did not resolve in the actor's workspace. `ownerOrgId`
 * is the workspace the referenced row actually lives in, or `null` if it does not exist.
 */
function refuseReference(
  actor: Actor,
  ownerOrgId: OrgId | null,
  entity: string,
  id: string,
): never {
  if (ownerOrgId !== null) assertOrgScope(actor, ownerOrgId);
  throw new NotFoundError(entity, id);
}

/** A parent issue must be a live issue of the same project. */
export async function assertLiveParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(actor.orgId, parentId);
  if (parent === null) {
    refuseReference(actor, await issueRepo.findIssueOrgId(parentId), "Issue", parentId);
  }
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Labels must be this workspace's own labels. */
export async function assertWorkspaceLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  const own = await labelRepo.listOwnLabelIds(actor.orgId, labelIds);
  for (const labelId of labelIds) {
    if (own.has(labelId)) continue;
    refuseReference(actor, await labelRepo.findLabelOrgId(labelId), "Label", labelId);
  }
}

/** An assignee or a project lead must be a current member of the workspace. */
export async function assertCurrentMember(
  actor: Actor,
  userId: UserId,
): Promise<void> {
  const current = await memberRepo.listCurrentMemberUserIds(actor.orgId, [userId]);
  if (!current.has(userId)) {
    throw new NotFoundError("Member", userId);
  }
}

/** A reply must target a live, top-level comment on the same issue. */
export async function assertReplyTarget(
  actor: Actor,
  issueId: IssueId,
  parentId: CommentId,
): Promise<void> {
  const parent = await commentRepo.findCommentById(actor.orgId, parentId);
  if (parent === null) {
    refuseReference(actor, await commentRepo.findCommentOrgId(parentId), "Comment", parentId);
  }
  if (isArchived(parent) || parent.issueId !== issueId || parent.parentId !== null) {
    throw new NotFoundError("Comment", parentId);
  }
}

