}

describe("parent issue", () => {
  it("refuses a parent from another workspace as tenant scope", async () => {
    const before = await issueCount(acme.org.id);
    await expect(
      issueService.createIssue(
        acme.actors.member,
        { ...issueInput(acme.org.id, acme.project.id, { title: "child" }), parentId: northIssue.id },
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await issueCount(acme.org.id)).toBe(before);
  });

  it("refuses a parent from another project as not found", async () => {
    const parent = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, otherProject.id, { title: "other proj parent" }),
    );
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "child" }),
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent as not found", async () => {
    const parent = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "to archive" }),
    );
    await issueService.archiveIssue(north.actors.admin, north.org.id, parent.id);
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "child" }),
        parentId: parent.id,
      }),
    ).rejects.toMatchObject({ code: "not_found" });
  });

  it("refuses a missing parent as not found", async () => {
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "child" }),
        parentId: "01MISSINGMISSINGMISSINGAAA" as never,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("accepts a live parent in the same project", async () => {
    const child = await issueService.createIssue(north.actors.member, {
      ...issueInput(north.org.id, north.project.id, { title: "good child" }),
      parentId: northIssue.id,
