import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let northIssue: Issue;
let otherProject: Awaited<ReturnType<typeof projectRepo.insertProject>>;

const body = (text: string) => text;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind");
  acme = await createTenant("acme");
  northIssue = await issueService.createIssue(
    north.actors.member,
    issueInput(north.org.id, north.project.id, { title: "Northwind only" }),
  );
  otherProject = await projectRepo.insertProject({
    orgId: north.org.id,
    name: "north other",
    slug: "other",
    key: "OTH",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
});

afterAll(() => cleanup());

async function issueCount(orgId: string): Promise<number> {
  const page = await issueRepo.listIssues({ orgId: orgId as never, limit: 500, cursor: null, includeArchived: true });
  return page.total;
}

describe("parent issue", () => {
  it("refuses a parent from another workspace as tenant scope", async () => {
    const before = await issueCount(acme.org.id);
    await expect(
      issueService.createIssue(
        acme.actors.member,
        { ...issueInput(acme.org.id, acme.project.id, { title: "child" }), parentId: northIssue.id },
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await issueCount(acme.org.id)).toBe(before);
  });

  it("refuses a parent from another project as not found", async () => {
    const parent = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, otherProject.id, { title: "other proj parent" }),
    );
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "child" }),
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent as not found", async () => {
    const parent = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "to archive" }),
    );
    await issueService.archiveIssue(north.actors.admin, north.org.id, parent.id);
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "child" }),
        parentId: parent.id,
      }),
    ).rejects.toMatchObject({ code: "not_found" });
  });

  it("refuses a missing parent as not found", async () => {
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "child" }),
        parentId: "01MISSINGMISSINGMISSINGAAA" as never,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("accepts a live parent in the same project", async () => {
    const child = await issueService.createIssue(north.actors.member, {
      ...issueInput(north.org.id, north.project.id, { title: "good child" }),
      parentId: northIssue.id,
    });
    expect(child.parentId).toBe(northIssue.id);
  });
});

describe("labels", () => {
  it("refuses a label from another workspace and creates nothing", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "acme-secret-project",
      color: "#000000",
      description: null,
    });
    const before = await issueCount(north.org.id);
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "labelled" }),
        labelIds: [foreign.id],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await issueCount(north.org.id)).toBe(before);
  });

  it("refuses a missing label as not found and leaves the issue unchanged on update", async () => {
    await expect(
      issueService.updateIssue(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        title: "should not stick",
        labelIds: ["01MISSINGMISSINGMISSINGAAA" as never],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const still = await issueRepo.findIssueById(north.org.id, northIssue.id);
    expect(still?.title).toBe("Northwind only");
  });

  it("never shows a foreign label attached to an issue", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "acme-leak",
      color: "#000000",
      description: null,
    });
    const own = await labelRepo.insertLabel({
      orgId: north.org.id,
      name: "north-own",
      color: "#111111",
      description: null,
    });
    // Simulate a legacy row: a join row in north pointing at acme's label.
    const { getDb, issueLabels } = await import("@/server/db");
    getDb()
      .insert(issueLabels)
      .values([
        { orgId: north.org.id, issueId: northIssue.id, labelId: foreign.id },
        { orgId: north.org.id, issueId: northIssue.id, labelId: own.id },
      ])
      .run();
    const detail = await issueService.getIssue(north.actors.member, north.org.id, northIssue.id);
    expect(detail.labels.map((l) => l.id)).toEqual([own.id]);
  });
});

describe("assignee and lead", () => {
  it("refuses a non-member assignee and assigns nothing", async () => {
    const stranger = acme.userIds.member;
    await expect(
      issueService.assignIssue(north.actors.admin, {
        orgId: north.org.id,
        issueId: northIssue.id,
        assigneeId: stranger,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const still = await issueRepo.findIssueById(north.org.id, northIssue.id);
    expect(still?.assigneeId).toBeNull();
  });

  it("refuses a removed member as create-time assignee", async () => {
    const member = await memberRepo.findMember(north.org.id, north.userIds.viewer);
    await memberRepo.archiveMember(north.org.id, member!.id);
    await expect(
      issueService.createIssue(
        north.actors.owner,
        issueInput(north.org.id, north.project.id, { title: "to viewer", assigneeId: north.userIds.viewer }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a non-member project lead and creates nothing", async () => {
    const before = await projectRepo.listProjects({ orgId: north.org.id, limit: 100, cursor: null });
    await expect(
      projectService.createProject(north.actors.owner, {
        orgId: north.org.id,
        name: "stranger led",
        slug: "stranger-led",
        key: "STR",
        description: null,
        visibility: "org",
        leadId: acme.userIds.owner,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const after = await projectRepo.listProjects({ orgId: north.org.id, limit: 100, cursor: null });
    expect(after.total).toBe(before.total);
  });

  it("refuses a non-member project lead on update", async () => {
    await expect(
      projectService.updateProject(north.actors.owner, {
        orgId: north.org.id,
        projectId: north.project.id,
        leadId: acme.userIds.owner,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const p = await projectRepo.findProjectById(north.org.id, north.project.id);
    expect(p?.leadId).toBe(north.userIds.owner);
  });
});

describe("replies", () => {
  let top: Awaited<ReturnType<typeof commentService.createComment>>;
  let otherIssue: Issue;

  beforeAll(async () => {
    top = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: body("top"),
      parentId: null,
      mentionedUserIds: [],
    });
    otherIssue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "other issue" }),
    );
  });

  it("refuses a reply to a comment on a different issue", async () => {
    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: otherIssue.id,
        body: "wrong issue",
        parentId: top.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentRepo.listThread(north.org.id, otherIssue.id)).resolves.toEqual([]);
  });

  it("refuses a reply to a deleted comment", async () => {
    const doomed = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "doomed",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(north.actors.member, { orgId: north.org.id, commentId: doomed.id });
    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "late reply",
        parentId: doomed.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a reply to a reply", async () => {
    const reply = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "a reply",
      parentId: top.id,
      mentionedUserIds: [],
    });
    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "reply to reply",
        parentId: reply.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a reply to a comment in another workspace as tenant scope", async () => {
    const acmeIssue = await issueService.createIssue(
      acme.actors.member,
      issueInput(acme.org.id, acme.project.id, { title: "acme issue" }),
    );
    const acmeTop = await commentService.createComment(acme.actors.member, {
      orgId: acme.org.id,
      issueId: acmeIssue.id,
      body: "acme top",
      parentId: null,
      mentionedUserIds: [],
    });
    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "cross",
        parentId: acmeTop.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("accepts a live top-level reply on the same issue", async () => {
    const reply = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "fine",
      parentId: top.id,
      mentionedUserIds: [],
    });
    expect(reply.parentId).toBe(top.id);
  });
});

describe("mentions", () => {
  it("drops composer ids and @handles of non-members, and notifies only members", async () => {
    const received: { mentionedUserIds: readonly string[] }[] = [];
    const off = subscribe("comment.created", (payload) => {
      received.push(payload as never);
    });
    try {
      const member = await memberRepo.findMember(north.org.id, north.userIds.viewer);
      await memberRepo.archiveMember(north.org.id, member!.id);
      const comment = await commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "cc @acme.member @viewer @admin",
        parentId: null,
        mentionedUserIds: [acme.userIds.owner, north.userIds.viewer, north.userIds.owner],
      });
      expect(comment.mentionedUserIds).toEqual([north.userIds.admin, north.userIds.owner]);
      expect(received[0]?.mentionedUserIds).toEqual([north.userIds.admin, north.userIds.owner]);
    } finally {
      off();
    }
  });
});

